description:
Template parameters can be **values** as well as types. Write `FixedArray<T, N>`, whose length `N` is part of its type and known at compile time.

- stores `N` elements of type `T`, all value-initialised;
- `constexpr std::size_t size() const` returns `N`;
- `T& operator[](std::size_t)` and a const version;
- `void fill(const T& value)` sets every element.

starter.solution.cpp:
#include <cstddef>

// template <typename T, std::size_t N>
// class FixedArray ...

solution.solution.cpp:
#include <cstddef>

template <typename T, std::size_t N>
class FixedArray
{
public:
    constexpr std::size_t size() const { return N; }

    T& operator[](std::size_t i) { return m_data[i]; }
    const T& operator[](std::size_t i) const { return m_data[i]; }

    void fill(const T& value)
    {
        for (std::size_t i{ 0 }; i < N; ++i)
        {
            m_data[i] = value;
        }
    }

private:
    T m_data[N]{};
};

unitTests:
static_assert(FixedArray<int, 5>{}.size() == 5, "size() should be usable at compile time");
static_assert(sizeof(FixedArray<char, 16>) == 16, "it should hold exactly N elements and nothing else");
static_assert(!std::is_same_v<FixedArray<int, 3>, FixedArray<int, 4>>);

TEST("starts zeroed") { const FixedArray<int, 4> a{}; CHECK_EQ(a[0], 0); CHECK_EQ(a[3], 0); }
TEST("read, write, fill") { FixedArray<std::string, 3> a{}; a[1] = "mid"; CHECK_EQ(a[1], "mid"); a.fill("x"); CHECK_EQ(a[0], "x"); CHECK_EQ(a[2], "x"); CHECK_EQ(a.size(), 3u); }

